code.css:
.pw2{display:block;margin-bottom:6px;font:600 14px system-ui,sans-serif}
.pw2__f{display:flex;width:300px;border:1px solid #8a8a8a;border-radius:8px;overflow:hidden}
.pw2__f input{flex:1;min-width:0;min-height:44px;padding:0 12px;border:0;font:16px system-ui,sans-serif}
.pw2__f button{padding:0 14px;border:0;border-left:1px solid #d4d4d4;background:#fff;font:600 13px system-ui,sans-serif;cursor:pointer}

code.js:
document.querySelectorAll('.pw2__f').forEach(field => {
  const input = field.querySelector('input'), toggle = field.querySelector('button');
  toggle.addEventListener('click', () => {
    const show = input.type === 'password';
    input.type = show ? 'text' : 'password';
    toggle.setAttribute('aria-pressed', String(show)); toggle.textContent = show ? 'Hide' : 'Show';
  });
});
